function checkDiskUsage(response, { warning, critical }, previous = {}) {
  if (
    !Number.isInteger(warning) ||
    !Number.isInteger(critical) ||
    warning < 1 ||
    critical <= warning ||
    critical > 100
  ) {
    throw Error("Set whole-number disk thresholds with 1 ≤ warning < critical ≤ 100.");
  }
  if (response.code !== 0 || response.signal || typeof response.stdout !== "string") {
    throw Error("The remote df -P command did not complete successfully.");
  }
  const [header, ...lines] = response.stdout.trim().split(/\r?\n/);
  const format =
    /^Filesystem\s+(512|1024|1K)-blocks\s+Used\s+Available\s+(?:Capacity|Use%)\s+Mounted on$/i.exec(
      header.trim(),
    );
  const rows = lines.filter((line) => line.trim());
  if (!format || !rows.length)
    throw Error("The remote host did not return a compatible df -P table.");
  const blockBytes = format[1] === "512" ? 512 : 1024;
  const levels = new Map(Object.entries(previous));
  const mounts = new Set();
  const alerts = [];
  for (const line of rows) {
    const match = /^\s*(.*?)\s+(\d+)\s+(-?\d+)\s+(-?\d+)\s+(\d+)%\s+(.+?)\s*$/.exec(line);
    if (!match) throw Error("A remote df -P row has an unexpected format.");
    const [, device, , , available, percentage, mount] = match;
    const usedPct = Number(percentage);
    if (
      !device ||
      !mount ||
      !Number.isSafeInteger(usedPct) ||
      !Number.isSafeInteger(Number(available)) ||
      mounts.has(mount)
    )
      throw Error("A remote df -P row has an invalid or repeated mount.");
    mounts.add(mount);
    const level = usedPct >= critical ? "critical" : usedPct >= warning ? "warning" : "ok";
    if (level === (levels.get(mount) ?? "ok")) continue;
    if (level === "ok") {
      levels.delete(mount);
      alerts.push("[OK] " + mount + " back below threshold (" + usedPct + "%)");
    } else {
      levels.set(mount, level);
      const free = ((Number(available) * blockBytes) / 1073741824).toFixed(1);
      const severity = level === "critical" ? "[CRITICAL]" : "[WARNING]";
      alerts.push(
        severity + " " + mount + " (" + device + "): " + usedPct + "% used, " + free + " GiB free",
      );
    }
  }
  return {
    hasAlerts: alerts.length > 0,
    message: alerts.join("\n"),
    levels: Object.fromEntries(levels),
  };
}
const thresholds = { warning: 80, critical: 90 };
const state = $getWorkflowStaticData("global");
const result = checkDiskUsage($input.first().json, thresholds, state.diskLevels);
return [{ json: result, pairedItem: { item: 0 } }];

const receipt = $input.first().json;
const telegramDelivered = receipt.ok === true && Number.isInteger(receipt.result?.message_id);
const smtpAccepted = Array.isArray(receipt.accepted) && receipt.accepted.length > 0;
if (!telegramDelivered && !smtpAccepted) {
  throw Error("The notification service did not return a delivery receipt.");
}
const alert = $("Evaluate disk thresholds").item.json;
$getWorkflowStaticData("global").diskLevels = alert.levels;
return [{ json: { message: alert.message }, pairedItem: { item: 0 } }];
